pe="hidden" name="company_id" value="<?= (int)$companyId ?>"><button class="btn btn-success"><i data-lucide="user-plus" class="me-1"></i>Import valid rows</button></form><?php else: ?><span class="badge text-bg-secondary"><?= e(str_replace('_',' ',$batch['status'])) ?></span><?php endif; ?></div></div>
